-- Sales partner onboarding and cafe service revenue. No creator royalty changes.
CREATE TABLE IF NOT EXISTS v5_sales_policy(id INTEGER PRIMARY KEY CHECK(id=1),version INTEGER NOT NULL DEFAULT 0,join_fee_krw INTEGER CHECK(join_fee_krw>=0),monthly_fee_tl INTEGER NOT NULL DEFAULT 50000,manager_bps INTEGER NOT NULL DEFAULT 2500 CHECK(manager_bps BETWEEN 0 AND 5000),dj_bps INTEGER NOT NULL DEFAULT 2500 CHECK(dj_bps BETWEEN 0 AND 5000),updated_by INTEGER,reason TEXT,updated_at TEXT,CHECK(manager_bps+dj_bps=5000));
INSERT OR IGNORE INTO v5_sales_policy(id)VALUES(1);
CREATE TABLE IF NOT EXISTS v5_sales_policy_history(version INTEGER PRIMARY KEY,data_json TEXT NOT NULL,actor_id INTEGER NOT NULL,created_at TEXT DEFAULT(datetime('now')));
CREATE TABLE IF NOT EXISTS v5_sales_members(user_id INTEGER PRIMARY KEY,country TEXT NOT NULL,display_name TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN('pending_deposit','simulated_paid','active','suspended')),fee_krw INTEGER NOT NULL,policy_version INTEGER NOT NULL,terms_version TEXT NOT NULL,terms_json TEXT NOT NULL,signature_json TEXT NOT NULL,signature_hash TEXT NOT NULL,signed_at TEXT NOT NULL,virtual_ref TEXT NOT NULL UNIQUE,invite_code TEXT NOT NULL UNIQUE,activation_basis TEXT,reviewed_by INTEGER,review_note TEXT,user_agent TEXT,created_at TEXT DEFAULT(datetime('now')));
CREATE TRIGGER IF NOT EXISTS v5_sales_contract_immutable BEFORE UPDATE OF country,fee_krw,policy_version,terms_version,terms_json,signature_json,signature_hash,signed_at ON v5_sales_members BEGIN SELECT RAISE(ABORT,'SIGNED_SALES_CONTRACT_IMMUTABLE'); END;
CREATE TABLE IF NOT EXISTS v5_sales_member_events(id TEXT PRIMARY KEY,user_id INTEGER NOT NULL,event_type TEXT NOT NULL,actor_id INTEGER NOT NULL,data_json TEXT NOT NULL,created_at TEXT DEFAULT(datetime('now')));
CREATE TABLE IF NOT EXISTS v5_sales_stores(channel_id TEXT PRIMARY KEY,manager_user_id INTEGER NOT NULL,dj_id INTEGER NOT NULL,kind TEXT NOT NULL CHECK(kind IN('cafe','store')),version INTEGER NOT NULL,owner_id INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS v5_sales_store_events(id TEXT PRIMARY KEY,channel_id TEXT NOT NULL,old_manager_id INTEGER,new_manager_id INTEGER NOT NULL,dj_id INTEGER NOT NULL,actor_owner_id INTEGER NOT NULL,version INTEGER NOT NULL,reason TEXT NOT NULL,created_at TEXT DEFAULT(datetime('now')));
CREATE TABLE IF NOT EXISTS v5_sales_payments(id TEXT PRIMARY KEY,ledger_transaction_id TEXT UNIQUE,idempotency_key TEXT UNIQUE,channel_id TEXT NOT NULL,payer_user_id INTEGER NOT NULL,manager_user_id INTEGER,dj_user_id INTEGER,amount_atoms INTEGER NOT NULL,manager_atoms INTEGER NOT NULL,dj_atoms INTEGER NOT NULL,platform_atoms INTEGER NOT NULL,manager_paid_atoms INTEGER NOT NULL,dj_paid_atoms INTEGER NOT NULL,policy_version INTEGER NOT NULL,origin_json TEXT NOT NULL,created_at TEXT DEFAULT(datetime('now')));
CREATE INDEX IF NOT EXISTS v5_sales_payments_manager ON v5_sales_payments(manager_user_id,created_at);
CREATE INDEX IF NOT EXISTS v5_sales_payments_dj ON v5_sales_payments(dj_user_id,created_at);
CREATE TABLE IF NOT EXISTS v5_sales_meters(channel_id TEXT PRIMARY KEY,dj_id INTEGER NOT NULL,last_ms INTEGER NOT NULL,version INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS v5_sales_channel_requests(request_key TEXT PRIMARY KEY,owner_id INTEGER NOT NULL,channel_id TEXT NOT NULL UNIQUE,input_hash TEXT NOT NULL,result_json TEXT NOT NULL,created_at TEXT DEFAULT(datetime('now')));
